function closeRealtime(manual=false){JARVIS.manualClose=manual;JARVIS.realtimeConnected=false;JARVIS.clientRealtimeReported=false;JARVIS.audioScene?.setJarvisSpeaking(false);JARVIS.audioScene?.setUserSpeaking(false);if($('#voiceTransport'))$('#voiceTransport').textContent='NIET ACTIEF';if($('#micPrivacy')&&JARVIS.ambientStream?.active)$('#micPrivacy').textContent='LOKAAL · STANDBY';if(manual){clearTimeout(JARVIS.reconnectTimer);JARVIS.reconnectTimer=null}const dc=JARVIS.dc,pc=JARVIS.pc;try{if(dc){dc.onopen=null;dc.onmessage=null;dc.onerror=null;dc.onclose=null;dc.close()}}catch{}try{if(pc){pc.ontrack=null;pc.onconnectionstatechange=null;pc.close()}}catch{}try{JARVIS.micStream?.getTracks().forEach(t=>t.stop())}catch{}if(JARVIS.audio){JARVIS.audio.pause();JARVIS.audio.srcObject=null}JARVIS.dc=null;JARVIS.pc=null;JARVIS.micStream=null;JARVIS.audio=null}
