const UICommandBus={async dispatch(cmd,result){if(!cmd||!cmd.type)return;if(cmd.type==='OPEN_ENGINE'&&MODULES[cmd.target])await openModule(cmd.target);else if(cmd.type==='CLOSE_ENGINE'){$('#layer').classList.add('hidden');focusOn(null)}else if(cmd.type==='OPEN_CONNECTOR'){await openModule('integraties');const card=document.querySelector(`[data-connector="${cssEscape(cmd.target)}"]`);card?.scrollIntoView({behavior:'smooth',block:'center'});card?.animate?.([{boxShadow:'0 0 0 rgba(255,157,61,0)'},{boxShadow:'0 0 30px rgba(255,157,61,.7)'},{boxShadow:'0 0 0 rgba(255,157,61,0)'}],{duration:1500})}else if(cmd.type==='FOCUS_NODE'&&MODULES[cmd.target])focusOn(cmd.target);else if(cmd.type==='CENTER_GRAPH')focusOn(null);else if(['SHOW_RESULTS','SHOW_REPORT','SHOW_TASK','SHOW_VEHICLE'].includes(cmd.type))showJarvisResult(result);else if(cmd.type==='SCROLL_TO'){const target=document.querySelector(`[data-connector="${cssEscape(cmd.target||'')}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'})}else if(cmd.type==='SET_JARVIS_STATE'&&cmd.state==='STANDBY')setTimeout(()=>endJarvisConversation(false),600);else if(cmd.type==='SHOW_NOTIFICATION')toast(cmd.message||'Jarvis-melding')},async apply(commands,result){for(const cmd of commands)await this.dispatch(cmd,result)}};
