function preferencePayload(){return {preferred_address:$('#preferredAddress').value,microphone_enabled:$('#microphoneEnabled').checked,wake_enabled:$('#wakeEnabled').checked,clap_enabled:$('#clapEnabled').checked,voice_enabled:$('#voiceEnabled').checked,music_enabled:$('#musicEnabled').checked,sfx_enabled:$('#sfxEnabled').checked,clap_sensitivity:Number($('#clapSensitivity').value),master_volume:Number($('#masterVolume').value),voice_volume:Number($('#voiceVolume').value),ambience_volume:Number($('#ambienceVolume').value),sfx_volume:Number($('#sfxVolume').value),muted:$('#audioMuted').checked,visual_quality:$('#visualQualitySelect').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,language:'nl-NL'}}
