async function savePreferences(){const desired=preferencePayload(),wasMic=JARVIS.preferences.microphone_enabled,r=await fetch('/api/jarvis/preferences',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(desired)}),j=await r.json();if(!r.ok)throw new Error(j.error||'Instellingen opslaan mislukt');applyPreferences(j.preferences);if(!wasMic&&j.preferences.microphone_enabled&&JARVIS.enabled){await ensureStandbyMic();initWakeListener();startClapDetector();startWakeListener()}toast('Audio- en privacyinstellingen persistent opgeslagen');$('#settingsPanel').classList.add('hidden')}
async function microphoneToggle(){JARVIS.preferences={...JARVIS.preferences,...preferencePayload()};if(!JARVIS.preferences.microphone_enabled){stopWakeListener();releaseStandbyMic();setJarvisState('MUTED','Microfoon uit · tekstbediening blijft beschikbaar');return}if(JARVIS.enabled){await ensureStandbyMic();initWakeListener();startClapDetector();startWakeListener()}}
function applyLiveControl(){JARVIS.preferences={...JARVIS.preferences,...preferencePayload()};renderPreferenceValues();JARVIS.audioScene?.setSettings(audioSettings());if(!JARVIS.preferences.voice_enabled){globalThis.speechSynthesis?.cancel();realtimeSend({type:'response.cancel'});JARVIS.fallbackSpeaking=false;JARVIS.audioScene?.setJarvisSpeaking(false)}if(JARVIS.preferences.wake_enabled&&JARVIS.enabled)startWakeListener();else stopWakeListener();if(JARVIS.preferences.clap_enabled&&JARVIS.enabled)startClapDetector();else stopClapDetector()}
function registerClientHandler(id,event,handler,required=false){const element=$('#'+id);if(!element){if(required)clientSubsystemFailure('JARVIS_UI',new Error(`Vereiste control ontbreekt: ${id}`));return false}element.addEventListener(event,handler);return true}
function registerJarvisHandlers(){const required=[registerClientHandler('mic','click',()=>activateJarvis().catch(error=>setJarvisState('ERROR',error.message)),true),registerClientHandler('initializeFoundly','click',()=>initializeFoundly().catch(error=>setJarvisState('ERROR',error.message)),true),registerClientHandler('send','click',submitTextCommand,true),registerClientHandler('command','keydown',event=>{if(event.key==='Enter'&&!event.repeat){event.preventDefault();submitTextCommand()}},true)];registerClientHandler('settingsToggle','click',()=>{$('#settingsPanel')?.classList.toggle('hidden');refreshMicrophoneDiagnostic()});registerClientHandler('settingsClose','click',()=>$('#settingsPanel')?.classList.add('hidden'));registerClientHandler('saveSettings','click',()=>savePreferences().catch(error=>setJarvisState('ERROR',error.message)));for(const id of ['masterVolume','voiceVolume','ambienceVolume','sfxVolume','audioMuted','voiceEnabled','musicEnabled','sfxEnabled','wakeEnabled','clapEnabled','clapSensitivity'])registerClientHandler(id,'input',applyLiveControl);registerClientHandler('visualQualitySelect','change',()=>{const quality=$('#visualQualitySelect')?.value;if(quality==='AUTO')neuralRuntime?.setAutoQuality?.();else if(quality)neuralRuntime?.setQuality(quality)});registerClientHandler('microphoneEnabled','change',()=>microphoneToggle().catch(error=>setJarvisState('ERROR',error.message)));registerClientHandler('fullscreen','click',()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.()});CLIENT_RUNTIME.jarvis_handlers=required.every(Boolean)?'REGISTERED':'INCOMPLETE';return required.every(Boolean)}
registerJarvisHandlers();if(globalThis.speechSynthesis)globalThis.speechSynthesis.onvoiceschanged=()=>fallbackVoice();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&JARVIS.enabled&&!JARVIS.realtimeConnected){JARVIS.audioScene?.resume().catch(()=>{});startClapDetector();startWakeListener()}});fetch('/api/jarvis/status').then(r=>r.ok?r.json():null).then(s=>{if(s?.conversation_timeout_ms)JARVIS.timeoutMs=s.conversation_timeout_ms;if(s?.preferences)applyPreferences(s.preferences);if(!s?.realtime_configured&&$('#listenText'))$('#listenText').textContent='Initialiseer eenmaal · Realtime niet geconfigureerd, browserfallback beschikbaar'}).catch(()=>{}).finally(()=>restoreJarvisWake());
async function loadSystemStatus(){try{const [hr,cr,jr]=await Promise.all([fetch('/api/health'),fetch('/api/connectors'),fetch('/api/jarvis/status')]);if(!hr.ok||!cr.ok||!jr.ok)throw new Error('Statusroute niet beschikbaar');const h=await hr.json(),c=await cr.json(),j=await jr.json();window.__foundlyConnectorStatus={connected:Number(c.connected||0),configured:Number(c.configured||0),total:Number(c.total||h.total_connectors||93),connectors:c.connectors||[],google:c.google||{},openai_search:c.openai_search||{configured:Boolean(h.openai_search_configured)}};if($('#coreState'))$('#coreState').textContent=j.core_available?'PASS':'FOUT';if($('#runtimeState'))$('#runtimeState').textContent=j.worker?.status||'ONBEKEND';if($('#memoryState'))$('#memoryState').textContent=j.memory?.durable?'PERSISTENT':(j.memory?.persisted?'LOKALE CACHE':'NIET BEWEZEN');if($('#connectorState'))$('#connectorState').textContent=`${window.__foundlyConnectorStatus.connected} LIVE`;}catch{window.__foundlyConnectorStatus={connected:0,configured:0,total:93,connectors:[]};if($('#coreState'))$('#coreState').textContent='FOUT';if($('#runtimeState'))$('#runtimeState').textContent='ONBEKEND';if($('#memoryState'))$('#memoryState').textContent='ONBEKEND';if($('#connectorState'))$('#connectorState').textContent='ONBEKEND';}}loadSystemStatus();setInterval(loadSystemStatus,30000);
function setPanelValue(id,value){const element=$('#'+id);if(element)element.textContent=String(value)}
async function loadDashboardSummary(){try{const response=await fetch('/api/dashboard/summary'),summary=await response.json();if(!response.ok)throw new Error(summary.error||'Dashboardstatus niet beschikbaar');setPanelValue('panelInventory',summary.business?.inventory_records??0);setPanelValue('panelLeads',summary.business?.leads??0);setPanelValue('panelCrm',summary.business?.crm_records??0);setPanelValue('panelTasks',summary.operations?.active_tasks??0);setPanelValue('panelRecords',summary.data_layer?.total_records??0);setPanelValue('panelProviders',summary.sources?.connected_providers??0);const sourceList=$('#liveSourceList');if(sourceList){sourceList.replaceChildren();const connected=summary.sources?.connected||[];if(!connected.length){const row=document.createElement('span');row.textContent='Geen providerprobe groen';sourceList.append(row)}else for(const source of connected){const row=document.createElement('span');row.textContent=source.name||source.id;sourceList.append(row)}}const stamp=$('#summaryObservedAt');if(stamp)stamp.textContent=new Date(summary.observed_at).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}catch{for(const id of ['panelInventory','panelLeads','panelCrm','panelTasks','panelRecords','panelProviders'])setPanelValue(id,'—');const sourceList=$('#liveSourceList');if(sourceList)sourceList.textContent='Status niet beschikbaar'}}loadDashboardSummary();setInterval(loadDashboardSummary,30000);
(function oauthFeedback(){const p=new URLSearchParams(location.search),boot=Number(p.get('bootstrap')||0);for(const id of ['google','meta','linkedin','tiktok','wix']){if(p.get(id)==='connected')setTimeout(async()=>{toast(`${id.toUpperCase()} gekoppeld${boot?' · '+boot+' records ingeladen':''}`);await loadSystemStatus();if(p.get('open')==='integraties')await renderIntegrations();refreshEvents()},300);if(p.get(id)==='error')setTimeout(()=>toast(`${id.toUpperCase()} koppeling fout: ${p.get('message')||'onbekend'}`),300)}if(p.has('open'))setTimeout(()=>openModule(p.get('open')),150);if([...p.keys()].some(k=>['google','meta','linkedin','tiktok','wix','message','bootstrap'].includes(k)))setTimeout(()=>history.replaceState({},'',location.pathname+(p.get('open')?'?open='+encodeURIComponent(p.get('open')):'')),1200)})();
const __qs=new URLSearchParams(location.search);if(__qs.get('open')==='integraties'){setTimeout(()=>openModule('integraties'),250)}
// Real operating-system event stream. Visual pulses are emitted only for new persisted events.
let lastVisualEventId=null;
async function refreshEvents(){try{const r=await fetch('/api/events'),j=await r.json();if(!r.ok)return;const rows=(j.events||[]),box=$('#events');if(!box)return;if(lastVisualEventId){const boundary=rows.findIndex(ev=>ev.id===lastVisualEventId);if(boundary>0)for(const ev of rows.slice(0,boundary).reverse())neuralRuntime?.event(ev)}lastVisualEventId=rows[0]?.id||lastVisualEventId;box.innerHTML='';for(const ev of rows.slice(0,8)){const d=document.createElement('div');d.className='ev';const at=ev.at?new Date(ev.at).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'}):'--:--';d.textContent=`${at} · ${ev.message}`;box.appendChild(d)}}catch{}}
refreshEvents();setInterval(refreshEvents,10000);
function toast(t){const el=$('#toast');el.textContent=t;el.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add('hidden'),2200)}
